verification.command:
node --input-type=module -e "import assert from 'node:assert/strict';import{readFileSync}from'node:fs';import{createHash}from'node:crypto';
const hash=v=>createHash('sha256').update(v).digest('hex'),file='docs/material-transform-origin-stage-survey.json',bytes=readFileSync(file),r=JSON.parse(bytes);
for(const f of [...r.sourceFingerprints,...r.reusedCoreProof])assert.equal(hash(readFileSync(f.file,'utf8').replace(/\r\n/g,'\n')),f.sha256,f.file);
const rawBytes=readFileSync(r.capturePath);assert.equal(hash(rawBytes),r.captureSha256);
const raw=JSON.parse(rawBytes),cases=new Map();for(const[k,entries]of[['static',raw.results],['interaction',raw.interactions]])for(const e of entries)cases.set(k+':'+e.family+'@'+e.profile+'/'+e.viewport.id+(e.state?'/'+e.state:''),e);
const ids=new Set(),counts={},reasons={};for(const o of r.observations){const key=o.case+'#'+o.element;assert.ok(!ids.has(key));ids.add(key);const e=cases.get(o.case),matches=e.styleInputs.filter(i=>i.id===o.element);assert.equal(matches.length,1);assert.deepEqual(o.inputTrees,e.inputTrees);assert.equal(o.referenceOrigin,matches[0].reference.transformOrigin);assert.equal(matches[0].astylar.transformOrigin,undefined);counts[o.status]=(counts[o.status]??0)+1;const reason=o.reason??o.attribution;reasons[reason]=(reasons[reason]??0)+1;if(o.status==='observed-declaration-stage-gap'){assert.equal(o.classification,'parity-harness-defect');for(const k of['inputEquivalent','candidateComputedOriginVerified','referenceBoxEqualityVerified','finalRasterVerified'])assert.equal(o[k],false);}}
assert.equal(ids.size,6938);assert.deepEqual(counts,{'observed-declaration-stage-gap':5570,unresolved:1368});assert.deepEqual(reasons,r.summary.reasons);assert.equal(r.mutationControls.length,350);assert.ok(r.mutationControls.every(c=>c.status==='unresolved'));assert.equal(new Set(r.mutationControls.map(c=>c.context)).size,35);assert.equal(Object.keys(r.summary.byFamily).length,36);
console.log(JSON.stringify({sourceFingerprints:r.sourceFingerprints.length,reusedCoreFiles:r.reusedCoreProof.length,uniqueCaseElementPairs:ids.size,counts,reasons,mutationControls:350,families:36,bytes:bytes.length,sha256:hash(bytes)}));"
